const L = params.length === undefined ? 21 : Math.max(1, Math.min(60, params.length));
const opacity = params.opacity === undefined ? 0.018 : Math.max(0, Math.min(0.05, params.opacity));
const material = { preset: 'glass', color: '#d5eaff', opacity: opacity, roughness: 1, metalness: 0 };
let envelope;
function face(nearWidth, farWidth, rise, rotation) {
  const slant = Math.sqrt(L * L + rise * rise);
  const angle = -Math.atan2(L, rise) * 180 / Math.PI;
  const mesh = api.extrude([[-nearWidth / 2, 0], [nearWidth / 2, 0], [farWidth / 2, slant], [-farWidth / 2, slant]], 0);
  mesh.rotate(angle, 0, 0).translate(0, 0.06, 0).rotate(0, 0, rotation).translate(0, 2.55, 0);
  if (envelope) envelope.merge(mesh);
  else envelope = mesh;
}
face(0.12, 12, 2.55 - 0.06, 0);
face(0.12, 12, 2.55 - 0.06, 180);
face(0.12, 5.1, 6 - 0.06, 90);
face(0.12, 5.1, 6 - 0.06, -90);
api.add(envelope, material);
return api.build();

