const dark = {preset:'rubber', color:'#101519', roughness:0.95};
const acoustic = {preset:'fabric', color:'#424349', roughness:1};
const equipment = {preset:'metal', color:'#949b9e', roughness:0.48, metalness:0.55};
const glass = {preset:'glass', color:'#adc6ce', opacity:0.22, roughness:0.08, metalness:0.05};
const lens = {preset:'glass', color:'#41778a', opacity:0.72, roughness:0.06, metalness:0.3};
const lamp = {preset:'emissive', color:params.lampColor, emissive:params.lampColor, emissiveIntensity:params.lampIntensity};
function box(w,h,d,x,y,z,m,solid){
 api.add(api.box(w,h,d).translate(x,y,z),m);
 if(solid) api.collider({kind:'box',halfExtents:[w/2,h/2,d/2],offset:[x,y,z]});
}
function pipe(points,r,m){api.add(api.tube(points,r,6),m);}
function post(x,y,z,h){box(0.045,h,0.045,x,y+h/2,z,stair,false);}
function rail(x,z1,y1,z2,y2){
 pipe([[x,y1,z1],[x,y2,z2]],0.026,stair);
 const dz=z2-z1, dy=y2-y1;
 api.collider({kind:'box',halfExtents:[0.028,0.028,Math.sqrt(dz*dz+dy*dy)/2],offset:[x,(y1+y2)/2,(z1+z2)/2],rotation:[-Math.atan2(dy,dz)*180/Math.PI,0,0]});
}
// Booth slab: its walking surface is exactly four metres above ground.
