box(2.1,0.65,0.12,1.95,5.1,-1.44,shell,true);
box(1.8,0.65,0.018,0,5.1,-1.455,glass,true);
for(let s=-1;s<=1;s+=2){
 box(0.055,0.76,0.17,s*0.925,5.1,-1.46,edge,false);
 box(1.9,0.055,0.17,0,5.1+s*0.3525,-1.46,edge,false);
}
box(1.96,0.035,0.25,0,4.735,-1.48,stair,false);
// West wall and east wall with an actual side-entry opening.
box(0.12,2.55,3,-2.94,5.275,0,shell,true);
box(0.12,2.55,1.475,2.94,5.275,-0.7625,shell,true);
box(0.12,2.55,0.675,2.94,5.275,1.1625,shell,true);
box(0.12,0.35,0.85,2.94,6.375,0.4,shell,true);
for(let z of [-0.025,0.825]) box(0.17,2.23,0.045,2.955,5.115,z,edge,false);
box(0.17,0.045,0.9,2.955,6.22,0.4,edge,false);
// Side door is parked open against the interior wall.
box(0.84,2.16,0.05,2.48,5.1,0.85,shell,false);
box(0.11,0.035,0.055,2.14,5.08,0.805,stair,false);
// Rear service doorway and hinged metal leaf.
box(3.9,2.55,0.12,-1.05,5.275,1.44,shell,true);
box(1,2.55,0.12,2.5,5.275,1.44,shell,true);
box(1.1,0.35,0.12,1.45,6.375,1.44,shell,true);
for(let x of [0.88,2.02]) box(0.045,2.25,0.17,x,5.125,1.46,edge,false);
box(1.18,0.045,0.17,1.45,6.24,1.46,edge,false);
const da=-params.rearDoorAngle;
function doorPart(w,h,d,x,y,z,m){api.add(api.box(w,h,d).translate(x,y,z).rotate(0,da,0).translate(0.91,4.04,1.49),m);}
doorPart(1.06,2.14,0.06,0.53,1.07,0,shell);
doorPart(0.92,0.13,0.015,0.53,0.2,0.04,stair);
doorPart(0.045,0.2,0.025,0.93,1.02,0.05,edge);
doorPart(0.16,0.032,0.065,0.865,1.05,0.085,stair);
for(let y of [0.25,1.05,1.85]) doorPart(0.035,0.11,0.09,0.015,y,0,stair);
const ar=da*Math.PI/180;
api.collider({kind:'box',halfExtents:[0.53,1.07,0.03],offset:[0.91+0.53*Math.cos(ar),5.11,1.49-0.53*Math.sin(ar)],rotation:[0,da,0]});
// Panel joints, corner uprights, and acoustic lining.
for(let x of [-2.96,2.96]) for(let z of [-1.46,1.46]) box(0.075,2.55,0.075,x,5.275,z,edge,false);
for(let x of [-2,-1,1,2]){
 box(0.018,0.7,0.018,x,4.39,-1.507,edge,false);
 box(0.018,1.04,0.018,x,5.99,-1.507,edge,false);
}
for(let z of [-1,-0.5,0,0.5,1]){
 box(0.018,2.43,0.018,-3.007,5.275,z,edge,false);
 box(0.045,2.15,0.43,-2.858,5.18,z,acoustic,false);
}
for(let x of [-2.35,-1.55,-0.75]) box(0.69,1.75,0.045,x,5.27,1.352,acoustic,false);
// Projector cabinet, adjustable feet, and distinct ventilated digital projector.
box(1.2,0.64,1.02,0,4.4,-0.17,edge,true);
box(1.32,0.065,1.12,0,4.7525,-0.17,stair,false);
for(let x of [-0.46,0.46]) for(let z of [-0.56,0.23]){
 api.add(api.cylinder(0.05,0.06,0.12,8).translate(x,4.08,z),stair);
 box(0.1,0.06,0.1,x,4.81,z,dark,false);
}
box(1.04,0.49,1.17,0,5.095,-0.22,equipment,true);
box(1.08,0.065,1.2,0,5.35,-0.22,edge,false);
box(0.99,0.22,0.04,0,5.02,0.383,edge,false);
for(let i=0;i<11;i++){
 const z=-0.67+i*0.084;
 box(0.016,0.25,0.035,0.528,5.12,z,dark,false);
 box(0.016,0.25,0.035,-0.528,5.12,z,dark,false);
 box(0.72,0.008,0.028,0,5.386,z,dark,false);
}
for(let i=0;i<9;i++) box(0.035,0.15,0.018,-0.39+i*0.058,5.055,0.411,stair,false);
box(0.15,0.09,0.014,0.36,5.23,0.413,dark,false);
box(0.11,0.045,0.009,0.36,5.235,0.424,lens,false);
api.add(api.cylinder(0.19,0.21,0.11,16).rotate(90,0,0).translate(0,5.1,-0.846),edge);
api.add(api.cylinder(0.14,0.17,0.37,16).rotate(90,0,0).translate(0,5.1,-1.04),edge);
api.add(api.cylinder(0.164,0.164,0.035,16).rotate(90,0,0).translate(0,5.1,-1.215),stair);
api.add(api.cylinder(0.132,0.132,0.012,20).rotate(90,0,0).translate(0,5.1,-1.237),lens);
// Cable tray, equipment power lead, and a small service shelf.
box(2.5,0.07,0.17,-0.75,4.14,1.22,edge,false);
pipe([[0.45,4.98,0.4],[0.65,4.8,0.65],[0.65,4.17,1.17],[-1.75,4.17,1.17]],0.017,dark);
box(0.2,0.26,0.08,-1.78,4.43,1.31,stair,false);
box(0.1,0.14,0.015,-1.78,4.44,1.259,dark,false);
box(1.1,0.05,0.4,-1.87,4.86,0.69,stair,false);
for(let x of [-2.25,-1.5]) pipe([[x,4.84,0.66],[x,4.53,1.3],[x,4.84,1.3]],0.023,edge);
// Warm caged service lamp inside the booth.
box(0.46,0.065,0.25,-1.6,6.49,0.25,edge,false);
