for(let x of [-1.76,-1.6,-1.44]) pipe([[x,6.46,0.14],[x,6.35,0.14],[x,6.35,0.36],[x,6.46,0.36]],0.012,stair);
// Exterior air louvre and slim roof flashing.
box(0.035,0.61,0.88,-3.02,5.79,0.38,edge,false);
for(let i=0;i<7;i++) box(0.075,0.035,0.8,-3.05,5.54+i*0.08,0.38,stair,false);
// Two 12-riser flights: 166.7 mm rise and 375 mm going.
const rise=2/12, going=0.375;
for(let f=0;f<2;f++){
 const xc=f===0?6.3:4.7;
 for(let i=0;i<12;i++){
  const y=f*2+(i+1)*rise;
  const z=f===0?0.75+(i+0.5)*going:5.25-(i+0.5)*going;
  box(1.3,0.055,going,xc,y-0.0275,z,stair,false);
  const front=f===0?z-going/2:z+going/2;
  box(1.3,rise-0.045,0.025,xc,y-rise/2-0.02,front,stair,false);
  box(1.25,0.012,0.055,xc,y+0.006,front+(f===0?0.025:-0.025),dark,false);
  api.collider({kind:'box',halfExtents:[0.65,rise/2,going/2],offset:[xc,y-rise/2,z]});
  // Three shallow tread drainage grooves.
  for(let j=0;j<3;j++) box(1.1,0.004,0.009,xc,y+0.002,z-0.09+j*0.09,edge,false);
 }
 const z1=f===0?0.75:5.25, z2=f===0?5.25:0.75;
 const y1=f*2+rise/2, y2=(f+1)*2+rise/2;
 const slope=-Math.atan2(y2-y1,z2-z1)*180/Math.PI;
 for(let x of [xc-0.58,xc+0.58]){
  api.add(api.box(0.09,0.2,Math.sqrt(4.5*4.5+4)).rotate(slope,0,0).translate(x,(y1+y2)/2-0.17,3),edge);
  rail(x,z1,y1+0.95,z2,y2+0.95);
  pipe([[x,y1+0.48,z1],[x,y2+0.48,z2]],0.019,stair);
  for(let j=0;j<=6;j++){
   const t=j/6, yy=y1+(y2-y1)*t, zz=z1+(z2-z1)*t;
   post(x,yy-0.05,zz,1.02);
  }
 }
}
// Full-width turn landing and upper bridge to the east entry.
box(3,0.14,0.75,5.5,1.93,5.625,stair,true);
box(2.4,0.14,0.75,4.2,3.93,0.375,stair,true);
box(1.4,0.08,0.7,6.3,0.04,0.4,edge,true);
// Landing deck joints and non-slip strips.
for(let i=0;i<6;i++){
 box(2.9,0.006,0.012,5.5,2.004,5.3+i*0.12,edge,false);
 box(2.27,0.006,0.012,4.2,4.004,0.07+i*0.12,edge,false);
}
// Structural landing legs with footplates and cross bracing.
for(let x of [4.08,6.92]) for(let z of [5.32,5.92]){
 box(0.13,1.86,0.13,x,0.93,z,edge,true);
 box(0.25,0.045,0.25,x,0.0225,z,stair,false);
}
for(let x of [3.16,5.28]){
 box(0.13,3.86,0.13,x,1.93,0.15,edge,true);
 box(0.25,0.045,0.25,x,0.0225,0.15,stair,false);
}
