pipe([[6.92,0.18,5.92],[4.08,1.8,5.92]],0.035,edge);
pipe([[3.16,0.2,0.15],[5.28,3.65,0.15]],0.035,edge);
// Guardrails at both exposed landings; openings align with the flights.
function guard(x1,z1,x2,z2,y){
 const len=Math.sqrt((x2-x1)*(x2-x1)+(z2-z1)*(z2-z1));
 const n=Math.ceil(len/0.7);
 for(let i=0;i<=n;i++){const t=i/n;post(x1+(x2-x1)*t,y,z1+(z2-z1)*t,1.1);}
 for(let h of [0.55,1.1]) pipe([[x1,y+h,z1],[x2,y+h,z2]],0.025,stair);
 const rot=Math.atan2(x2-x1,z2-z1)*180/Math.PI;
 api.collider({kind:'box',halfExtents:[0.03,0.55,len/2],offset:[(x1+x2)/2,y+0.55,(z1+z2)/2],rotation:[0,rot,0]});
 const toe=api.box(0.035,0.1,len).rotate(0,rot,0).translate((x1+x2)/2,y+0.05,(z1+z2)/2);api.add(toe,stair);
}
guard(4.04,5.96,6.96,5.96,2);
guard(4.04,5.25,4.04,5.96,2);
guard(6.96,5.25,6.96,5.96,2);
